package com.example.worker.notification.application.service; import com.example.worker.notification.application.port.NotificationRepository; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import java.time.*;
@Service public class NotificationRetentionService { private final NotificationRepository repository; public NotificationRetentionService(NotificationRepository repository){this.repository=repository;} @Scheduled(cron="0 0 3 * * *") public void deleteExpired(){repository.deleteCreatedBefore(Instant.now().minus(Duration.ofDays(30)));} }
